// GOOD CODE: Using a secure Java API to prevent SQL injection
import java.sql.*;

public String processInputSafe(String input) {
    // Use parameterized query to prevent SQL injection
    String query = "SELECT * FROM users WHERE username = ?";
    try (Connection conn = DriverManager.getConnection(
        "jdbc:mysql://localhost/test", "user", "password");
        PreparedStatement pstmt = conn.prepareStatement(query)) {
        pstmt.setString(1, input);
        ResultSet rs = pstmt.executeQuery();
        return rs.toString();
    } catch (SQLException ex) {
        // Handle exception, but input is never injected into the query
        throw new RuntimeException("Database error", ex);
    }
}
```

